(function($){
  if (!$) return;
  if (!$.fn.tagsinput) {
    $.fn.tagsinput = function(action, value) {
      if (action === "items") {
        var raw = this.val() || "";
        return raw ? String(raw).split(",").filter(Boolean) : [];
      }
      if (action === "add" && value !== undefined) {
        return this.each(function(){
          var current = this.value ? String(this.value).split(",").filter(Boolean) : [];
          current.push(value);
          this.value = current.join(",");
        });
      }
      if (action === "remove" && value !== undefined) {
        return this.each(function(){
          var current = this.value ? String(this.value).split(",").filter(Boolean) : [];
          this.value = current.filter(function(item){ return item !== value; }).join(",");
        });
      }
      return this;
    };
  }
})(window.jQueryZW || window.jQuery);
